import{_ as e,o as t,c as a,a2 as o}from"./chunks/framework.B7YvHKtj.js";const u=JSON.parse('{"title":"TVer (日剧 / 日本综娱) 平台使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/platforms/tver.md","filePath":"zh/docs/platforms/tver.md"}'),l={name:"zh/docs/platforms/tver.md"};function i(s,r,n,d,c,h){return t(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="tver-日剧-日本综娱-平台使用指南" tabindex="-1">TVer (日剧 / 日本综娱) 平台使用指南 <a class="header-anchor" href="#tver-日剧-日本综娱-平台使用指南" aria-label="Permalink to &quot;TVer (日剧 / 日本综娱) 平台使用指南&quot;">​</a></h1><p><a href="https://tver.jp/" target="_blank" rel="noreferrer">TVer</a> 是日本主流民营电视台联合推出的官方免费流媒体平台，包含大量最新的热播日剧、动漫与综娱节目。</p><hr><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><ul><li><strong>日剧生肉终结者</strong>：自动嗅探抓取 TVer 官方的原版日语字幕轨，通过 AI 实时转化为流畅自然的中日双语对照字幕。</li><li><strong>全屏自适应挂载</strong>：针对 TVer 播放器结构（VideoJS 与 EpisodePlayer 容器）进行了专门适配，无论是普通窗口还是全屏播放，控制按钮与字幕图层均精准嵌入播放器内部，绝不会偏移或溢出。</li><li><strong>商业广告智能屏蔽（Ad Muting）</strong>： <ul><li>TVer 视频在播放前和播放中经常插入日本电视商业广告。</li><li>CoWatcher 内置专属广告状态侦测器，在播放广告时自动静音并隐藏 AI 字幕，广告结束正片开始时立即毫秒级恢复翻译与渲染，不浪费任何 AI Token。</li></ul></li></ul><hr><h2 id="常见问题与技巧" tabindex="-1">常见问题与技巧 <a class="header-anchor" href="#常见问题与技巧" aria-label="Permalink to &quot;常见问题与技巧&quot;">​</a></h2><ol><li><strong>没有看到 AI 字幕怎么办？</strong><ul><li>确保当前播放的日剧节目在 TVer 原生播放器中支持「字幕」（TVer 播放器控制栏右下角有「字幕」图标）。</li><li>如果刚载入视频时还未就绪，按下 <strong><code>Alt + T</code></strong> 触发重试即可。</li></ul></li><li><strong>快捷键控制</strong>： <ul><li>随时按 <strong><code>Alt + T</code></strong> 开启/关闭字幕。</li></ul></li></ol>',8)])])}const p=e(l,[["render",i]]);export{u as __pageData,p as default};
